package io.github.wrightdk.repertory.data

import kotlin.random.Random
import kotlinx.serialization.Serializable
import kotlinx.serialization.json.Json

/**
 * A well-known person offered on the empty Home screen. Bundled in
 * `assets/suggestions.json`, generated by `scripts/generate_suggestions.py`,
 * so showing them needs no network.
 */
@Serializable
data class Suggestion(
    /** TMDB person id. */
    val id: Int,
    val name: String,
    /** TMDB department they're suggested for, e.g. "Directing". */
    val department: String,
)

private val json = Json { ignoreUnknownKeys = true }

internal fun parseSuggestions(text: String): List<Suggestion> = json.decodeFromString(text)

/**
 * A random [count] of [all], with at most [perDepartment] from any one
 * department so the handful isn't all directors.
 */
internal fun pickSuggestions(
    all: List<Suggestion>,
    count: Int,
    random: Random,
    perDepartment: Int = 2,
): List<Suggestion> {
    val taken = mutableMapOf<String, Int>()
    val picked = mutableListOf<Suggestion>()
    for (s in all.shuffled(random)) {
        if (picked.size == count) break
        val n = taken[s.department] ?: 0
        if (n < perDepartment) {
            picked += s
            taken[s.department] = n + 1
        }
    }
    // Too few departments to fill the handful under the cap: top up from the rest.
    if (picked.size < count) picked += (all - picked.toSet()).shuffled(random).take(count - picked.size)
    return picked
}
